// Construit titre + corps selon la table source du webhook Supabase.
const b = $json.body || $json;
const table = b.table || (b.record && b._table) || 'inconnu';
const rec = b.record || {};
let subject = '[Playbook] Nouvelle remontée joueuse';
let text = '';
switch (table) {
  case 'team_reviews':
    subject = '[Playbook] Ressenti bien-être équipe';
    text = `Une joueuse a soumis un ressenti d'équipe.\nDate: ${rec.date || ''}\nNote: ${rec.score ?? rec.rating ?? '?'}\nCommentaire: ${rec.comment || rec.note || '—'}`;
    break;
  case 'convocation_responses':
    if ((rec.status || '').toLowerCase() === 'absent') {
      subject = '[Playbook] Absence signalée';
      text = `Joueuse ${rec.player_id} absente à la convocation ${rec.convocation_id} (${rec.instance_date || ''}).\nMotif: ${rec.reason || '—'}`;
    } else { return []; } // seules les absences notifient
    break;
  case 'player_match_feedback':
    subject = '[Playbook] Ressenti post-match';
    text = `Ressenti post-match de ${rec.player_id} (match ${rec.match_id}).`;
    break;
  case 'player_wellness_log':
    const s = Number(rec.score ?? rec.wellness ?? 10);
    if (s > 4) return []; // n'alerte que sur score bas
    subject = '[Playbook] Bien-être bas signalé';
    text = `Score bien-être bas (${s}/10) pour ${rec.player_id} le ${rec.date || ''}.`;
    break;
  default:
    text = `Événement ${table}: ${JSON.stringify(rec)}`;
}
return [{ json: { subject, text } }];
